modules = [
    {
        "Title": "Circle Fundamentals",
        "VideoId": "O-cawByg2aA",
        "Explanation": "A circle is the set of all points equidistant from a center. The **Radius (r)** is the distance from center to edge. The **Diameter (d)** is the distance across through the center (d = 2r). **Circumference (C)** is the distance around the circle (C = 2πr). **Area (A)** is the space inside (A = πr²).",
        "KeyPoints": [
            "Radius (r): Center to edge.",
            "Diameter (d): 2 x Radius.",
            "Circumference: 2πr.",
            "Area: πr²."
        ],
        "Timeline": [
            {
                "Date": "250 BC",
                "Title": "Archimedes",
                "Description": "Approximated Pi accurately.",
                "Person": "Archimedes"
            }
        ],
        "FunFact": "A circle encloses the largest possible area for a given amount of perimeter!",
        "InteractiveElement": "<div class=\"interactive-box\"><h2>Circle Calculator</h2><input type='range' min='1' max='50' value='10' id='radInput'><div id='circleVis'></div><p>Radius: <span id='radOut'></span></p><p>Circumference: <span id='circOut'></span></p><p>Area: <span id='areaOut'></span></p><script>let radInput = document.getElementById('radInput');let circleVis = document.getElementById('circleVis');let radOut = document.getElementById('radOut');let circOut = document.getElementById('circOut');let areaOut = document.getElementById('areaOut');function updateCircle() {let r = radInput.value;circleVis.style.width = r * 10 + 'px';circleVis.style.height = r * 10 + 'px';radOut.innerText = r;circOut.innerText = (2 * Math.PI * r).toFixed(2);areaOut.innerText = (Math.PI * r * r).toFixed(2);}radInput.addEventListener('input', updateCircle);updateCircle();</script></div>",
        "audioSources": {}
    },
    {
        "Title": "Angles, Arcs & Sectors",
        "VideoId": "Fzaof9cX-PM",
        "Explanation": "A **Central Angle** has its vertex at the center. An **Inscribed Angle** has its vertex on the circle. The measure of a central angle equals its intercepted arc. An inscribed angle is half the intercepted arc. **Arc Length** is a portion of the circumference: (θ/360) * 2πr. **Sector Area** is a slice of the total area: (θ/360) * πr².",
        "KeyPoints": [
            "Central Angle = Arc Measure.",
            "Inscribed Angle = 1/2 Arc Measure.",
            "Arc Length = (degrees/360) * Circumference.",
            "Sector Area = (degrees/360) * Total Area."
        ],
        "Timeline": [
            {
                "Date": "2000 BC",
                "Title": "Babylonian Astronomy",
                "Description": "Divided circle into 360 degrees.",
                "Person": "Babylonians"
            }
        ],
        "FunFact": "We use 360 degrees likely because 360 is divisible by 24 different numbers, making math easier for ancient astronomers.",
        "InteractiveElement": "<div class=\"interactive-box\"><h2>Sector Solver</h2><input type='number' id='sectRadius' placeholder='Radius'><input type='number' id='sectAngle' placeholder='Angle (deg)'><button id='calcSector'>Calculate</button><div id='sectResults'></div><script>document.getElementById('calcSector').addEventListener('click', function() {let radius = document.getElementById('sectRadius').value;let angle = document.getElementById('sectAngle').value;let arcLength = (angle/360)*2*Math.PI*radius;let sectorArea = (angle/360)*Math.PI*radius*radius;document.getElementById('sectResults').innerHTML = `<p>Arc Length: ${arcLength.toFixed(2)}</p><p>Sector Area: ${sectorArea.toFixed(2)}</p>`;});</script></div>",
        "audioSources": {}
    },
    {
        "Title": "Coordinate Geometry: Distance & Midpoint",
        "VideoId": "",
        "Explanation": "On a coordinate plane, the **Distance Formula** finds the length between two points (x1, y1) and (x2, y2) using the Pythagorean theorem: d = √((x2-x1)² + (y2-y1)²). The **Midpoint Formula** finds the exact center: ((x1+x2)/2, (y1+y2)/2).",
        "KeyPoints": [
            "Distance is like finding the hypotenuse.",
            "Midpoint is just the average of the coordinates."
        ],
        "Timeline": [
            {
                "Date": "1637",
                "Title": "La Géométrie",
                "Description": "Published the foundation of analytic geometry.",
                "Person": "René Descartes"
            }
        ],
        "FunFact": "Legend says Descartes invented the coordinate system while watching a fly crawl on his ceiling!",
        "InteractiveElement": "<div class=\"interactive-box\"><h2>Coordinate Lab</h2><input type='number' id='x1' placeholder='x1'><input type='number' id='y1' placeholder='y1'><input type='number' id='x2' placeholder='x2'><input type='number' id='y2' placeholder='y2'><button id='calcCoord'>Analyze Points</button><div id='coordResults'></div><script>document.getElementById('calcCoord').addEventListener('click', function() {let x1 = parseFloat(document.getElementById('x1').value);let y1 = parseFloat(document.getElementById('y1').value);let x2 = parseFloat(document.getElementById('x2').value);let y2 = parseFloat(document.getElementById('y2').value);let distance = Math.sqrt(Math.pow(x2-x1, 2) + Math.pow(y2-y1, 2));let midpointX = (x1+x2)/2;let midpointY = (y1+y2)/2;document.getElementById('coordResults').innerHTML = `<p>Distance: ${distance.toFixed(2)}</p><p>Midpoint: (${midpointX.toFixed(2)}, ${midpointY.toFixed(2)})</p>`;});</script></div>",
        "audioSources": {}
    },
    {
        "Title": "Slopes & Lines",
        "VideoId": "",
        "Explanation": "The **Slope (m)** represents the steepness of a line: m = (y2-y1)/(x2-x1). **Parallel Lines** never touch and have EQUAL slopes. **Perpendicular Lines** intersect at 90° and have NEGATIVE RECIPROCAL slopes (product is -1).",
        "KeyPoints": [
            "Slope = Rise / Run.",
            "Parallel Slopes are Equal.",
            "Perpendicular Slopes are Negative Reciprocals."
        ],
        "Timeline": [
            {
                "Date": "300 BC",
                "Title": "The Elements",
                "Description": "Systematized geometry axioms.",
                "Person": "Euclid"
            }
        ],
        "FunFact": "A vertical line has an 'undefined' slope because you cannot divide by zero (the run is zero).",
        "InteractiveElement": "<div class=\"interactive-box\"><h2>Slope Detective</h2><input type='number' id='x1' placeholder='x1'><input type='number' id='y1' placeholder='y1'><input type='number' id='x2' placeholder='x2'><input type='number' id='y2' placeholder='y2'><button id='calcSlope'>Get Slope Info</button><div id='slopeResults'></div><script>document.getElementById('calcSlope').addEventListener('click', function() {let x1 = parseFloat(document.getElementById('x1').value);let y1 = parseFloat(document.getElementById('y1').value);let x2 = parseFloat(document.getElementById('x2').value);let y2 = parseFloat(document.getElementById('y2').value);let slope = (y2-y1)/(x2-x1);let parallelSlope = slope;let perpendicularSlope = -1/slope;if (x1 === x2) {document.getElementById('slopeResults').innerHTML = '<p>Slope: Undefined</p><p>Parallel Slope: Undefined</p><p>Perpendicular Slope: 0</p>';} else {document.getElementById('slopeResults').innerHTML = `<p>Slope: ${slope.toFixed(2)}</p><p>Parallel Slope: ${parallelSlope.toFixed(2)}</p><p>Perpendicular Slope: ${perpendicularSlope.toFixed(2)}</p>`;}});
</script></div>",
        "audioSources": {}
    }
];
initModules();

